const pptxgen = require("pptxgenjs");

// Color palette: Ethereum-inspired dark theme
// Primary: 1A1A2E (deep navy/black)
// Secondary: 16213E (slightly lighter navy)
// Accent: 00D4AA (Ethereum teal/mint)
// Text: E0E0E0 (light gray)
// Muted: 8B8B8B

const COLORS = {
  primary: "1A1A2E",
  secondary: "16213E",
  accent: "00D4AA",
  accentLight: "5EEAD4",
  text: "E0E0E0",
  textDark: "1A1A2E",
  muted: "8B8B8B",
  cardBg: "1E2A4A",
  white: "FFFFFF",
  chart1: "00D4AA",
  chart2: "0D9488",
  chart3: "14B8A6",
  chart4: "5EEAD4",
  chart5: "2DD4BF",
  red: "F87171",
  orange: "FB923C",
  yellow: "FACC15",
  purple: "A78BFA"
};

let pres = new pptxgen();
pres.layout = "LAYOUT_16x9";
pres.title = "Ultra Sound Money: Ethereum's Post-Merge Supply Dynamics and Monetary Premium";
pres.author = "Research";
pres.subject = "Ethereum Supply Dynamics";

// Define slide masters
pres.defineSlideMaster({
  title: "TITLE_SLIDE",
  background: { color: COLORS.primary },
  objects: []
});

pres.defineSlideMaster({
  title: "CONTENT_SLIDE",
  background: { color: COLORS.primary },
  objects: []
});

function addHeaderBar(slide, title) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 0, w: 10, h: 0.85,
    fill: { color: COLORS.secondary }
  });
  slide.addText(title, {
    x: 0.5, y: 0.18, w: 9, h: 0.5,
    fontSize: 22, fontFace: "Arial", bold: true,
    color: COLORS.accent, align: "left", valign: "middle"
  });
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0.5, y: 0.72, w: 1.2, h: 0.04,
    fill: { color: COLORS.accent }
  });
}

function addFooter(slide) {
  slide.addShape(pres.shapes.RECTANGLE, {
    x: 0, y: 5.45, w: 10, h: 0.175,
    fill: { color: COLORS.secondary }
  });
  slide.addText("Source: ultrasound.money  |  Data as of latest update", {
    x: 0.5, y: 5.45, w: 9, h: 0.175,
    fontSize: 8, fontFace: "Arial",
    color: COLORS.muted, align: "left", valign: "middle"
  });
}

// ============================================
// SLIDE 1: Title Slide
// ============================================
let slide1 = pres.addSlide({ masterName: "TITLE_SLIDE" });
slide1.background = { color: COLORS.primary };

// Decorative accent bar on left
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0, y: 0, w: 0.12, h: 5.625,
  fill: { color: COLORS.accent }
});

// Title
slide1.addText("Ultra Sound Money", {
  x: 0.7, y: 1.4, w: 8.5, h: 0.9,
  fontSize: 48, fontFace: "Arial", bold: true,
  color: COLORS.white, align: "left", valign: "middle"
});

// Subtitle
slide1.addText("Ethereum's Post-Merge Supply Dynamics & Monetary Thesis", {
  x: 0.7, y: 2.3, w: 8.5, h: 0.5,
  fontSize: 20, fontFace: "Arial",
  color: COLORS.accent, align: "left", valign: "middle"
});

// Divider line
slide1.addShape(pres.shapes.LINE, {
  x: 0.7, y: 2.95, w: 3.5, h: 0,
  line: { color: COLORS.accent, width: 2 }
});

// Key stats row
slide1.addText("Current Supply: 121,603,980 ETH", {
  x: 0.7, y: 3.3, w: 4, h: 0.35,
  fontSize: 14, fontFace: "Arial", bold: true,
  color: COLORS.text, align: "left", valign: "middle"
});
slide1.addText("ETH Price: $2,243 USD", {
  x: 0.7, y: 3.7, w: 4, h: 0.35,
  fontSize: 14, fontFace: "Arial", bold: true,
  color: COLORS.text, align: "left", valign: "middle"
});
slide1.addText("Base Gas: 0.1 Gwei (historic low)", {
  x: 0.7, y: 4.1, w: 4, h: 0.35,
  fontSize: 14, fontFace: "Arial", bold: true,
  color: COLORS.text, align: "left", valign: "middle"
});

// Audience tag
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 0.7, y: 4.7, w: 3.8, h: 0.4,
  fill: { color: COLORS.cardBg },
  line: { color: COLORS.accent, width: 1 }
});
slide1.addText("For crypto-native investors & Ethereum ecosystem participants", {
  x: 0.7, y: 4.7, w: 3.8, h: 0.4,
  fontSize: 11, fontFace: "Arial",
  color: COLORS.accentLight, align: "center", valign: "middle"
});

// Right side decorative element
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 7.5, y: 1.8, w: 2.2, h: 2.2,
  fill: { color: COLORS.accent, transparency: 8 }
});
slide1.addShape(pres.shapes.RECTANGLE, {
  x: 7.8, y: 2.1, w: 1.6, h: 1.6,
  fill: { color: COLORS.accent, transparency: 15 }
});
slide1.addText("Ξ", {
  x: 7.5, y: 1.8, w: 2.2, h: 2.2,
  fontSize: 72, fontFace: "Arial", bold: true,
  color: COLORS.accent, align: "center", valign: "middle",
  transparency: 30
});

addFooter(slide1);

// ============================================
// SLIDE 2: Supply Change Snapshot
// ============================================
let slide2 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
addHeaderBar(slide2, "ETH Supply Growing at +0.83%/Year with Only 192 ETH Burned in 7 Days");

// Left side: key stats
slide2.addText("7-Day Supply Change", {
  x: 0.5, y: 1.1, w: 4, h: 0.35,
  fontSize: 14, fontFace: "Arial", bold: true,
  color: COLORS.accent, align: "left", valign: "middle"
});

// Stat cards
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 1.5, w: 1.8, h: 0.9,
  fill: { color: COLORS.cardBg },
  line: { color: COLORS.accent, width: 1 }
});
slide2.addText("+19,445.89", {
  x: 0.5, y: 1.55, w: 1.8, h: 0.4,
  fontSize: 22, fontFace: "Arial", bold: true,
  color: COLORS.accent, align: "center", valign: "middle"
});
slide2.addText("Net ETH Added", {
  x: 0.5, y: 1.95, w: 1.8, h: 0.35,
  fontSize: 10, fontFace: "Arial",
  color: COLORS.muted, align: "center", valign: "middle"
});

slide2.addShape(pres.shapes.RECTANGLE, {
  x: 2.5, y: 1.5, w: 1.8, h: 0.9,
  fill: { color: COLORS.cardBg },
  line: { color: COLORS.red, width: 1 }
});
slide2.addText("+0.83%", {
  x: 2.5, y: 1.55, w: 1.8, h: 0.4,
  fontSize: 22, fontFace: "Arial", bold: true,
  color: COLORS.red, align: "center", valign: "middle"
});
slide2.addText("Annualized Growth", {
  x: 2.5, y: 1.95, w: 1.8, h: 0.35,
  fontSize: 10, fontFace: "Arial",
  color: COLORS.muted, align: "center", valign: "middle"
});

slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 2.6, w: 1.8, h: 0.9,
  fill: { color: COLORS.cardBg },
  line: { color: COLORS.orange, width: 1 }
});
slide2.addText("0.01x", {
  x: 0.5, y: 2.65, w: 1.8, h: 0.4,
  fontSize: 22, fontFace: "Arial", bold: true,
  color: COLORS.orange, align: "center", valign: "middle"
});
slide2.addText("Issuance Offset Ratio", {
  x: 0.5, y: 3.05, w: 1.8, h: 0.35,
  fontSize: 10, fontFace: "Arial",
  color: COLORS.muted, align: "center", valign: "middle"
});

slide2.addShape(pres.shapes.RECTANGLE, {
  x: 2.5, y: 2.6, w: 1.8, h: 0.9,
  fill: { color: COLORS.cardBg },
  line: { color: COLORS.yellow, width: 1 }
});
slide2.addText("121.6M", {
  x: 2.5, y: 2.65, w: 1.8, h: 0.4,
  fontSize: 22, fontFace: "Arial", bold: true,
  color: COLORS.yellow, align: "center", valign: "middle"
});
slide2.addText("Total Supply (ETH)", {
  x: 2.5, y: 3.05, w: 1.8, h: 0.35,
  fontSize: 10, fontFace: "Arial",
  color: COLORS.muted, align: "center", valign: "middle"
});

// Right side: bar chart
slide2.addChart(pres.charts.BAR, [
  { name: "ETH Flow", labels: ["Issuance", "Burn", "Net Change"], values: [19638.29, -192.39, 19445.89] }
], {
  x: 4.8, y: 1.1, w: 4.8, h: 3.5,
  barDir: "col",
  chartColors: [COLORS.accent, COLORS.red, COLORS.yellow],
  chartArea: { fill: { color: COLORS.cardBg }, roundedCorners: true },
  catAxisLabelColor: COLORS.text,
  valAxisLabelColor: COLORS.muted,
  valGridLine: { color: "334155", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: COLORS.text,
  dataLabelFontSize: 10,
  showLegend: false,
  title: "7-Day Supply Flow (ETH)",
  titleColor: COLORS.text,
  titleFontSize: 12,
  titleBold: true
});

// Bottom insight
slide2.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 3.8, w: 4.3, h: 0.7,
  fill: { color: COLORS.cardBg },
  line: { color: COLORS.muted, width: 0.5 }
});
slide2.addText("Insight: Burns currently offset only ~1% of new issuance. At 0.1 Gwei average gas, the network is in a temporary inflationary regime — far from the deflationary dynamics seen during high-activity periods.", {
  x: 0.6, y: 3.85, w: 4.1, h: 0.6,
  fontSize: 10, fontFace: "Arial",
  color: COLORS.text, align: "left", valign: "middle"
});

addFooter(slide2);

// ============================================
// SLIDE 3: Gas and Burn Mechanics
// ============================================
let slide3 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
addHeaderBar(slide3, "Base Gas at Historic Lows: 0.1 Gwei Average Suppresses Fee Burn");

// Left: explanation
slide3.addText("EIP-1559 Burn Mechanism", {
  x: 0.5, y: 1.1, w: 4.2, h: 0.35,
  fontSize: 16, fontFace: "Arial", bold: true,
  color: COLORS.accent, align: "left", valign: "middle"
});

slide3.addText([
  { text: "Base fees are burned, permanently removing ETH from circulation.", options: { bullet: true, breakLine: true, color: COLORS.text, fontSize: 12 } },
  { text: "Tips and MEV go to validators — not burned.", options: { bullet: true, breakLine: true, color: COLORS.text, fontSize: 12 } },
  { text: "Low gas = low burn = supply inflation.", options: { bullet: true, breakLine: true, color: COLORS.text, fontSize: 12 } },
  { text: "Equilibrium requires ~22 Gwei sustained average.", options: { bullet: true, color: COLORS.text, fontSize: 12 } }
], {
  x: 0.5, y: 1.5, w: 4.2, h: 1.8,
  fontFace: "Arial", paraSpaceAfter: 6
});

// Gas gauge visualization
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0.5, y: 3.5, w: 4.2, h: 1.5,
  fill: { color: COLORS.cardBg },
  line: { color: COLORS.accent, width: 1 }
});
slide3.addText("Current Gas Market (7-Day)", {
  x: 0.7, y: 3.6, w: 3.8, h: 0.3,
  fontSize: 12, fontFace: "Arial", bold: true,
  color: COLORS.accent, align: "left", valign: "middle"
});

// Gauge bar background
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0.7, y: 4.0, w: 3.8, h: 0.25,
  fill: { color: "334155" }
});
// Current position marker (0.1 Gwei out of 22 Gwei target = tiny sliver)
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 0.7, y: 4.0, w: 0.017, h: 0.25,
  fill: { color: COLORS.red }
});
slide3.addText("0.1 Gwei (current)", {
  x: 0.7, y: 4.35, w: 1.5, h: 0.2,
  fontSize: 9, fontFace: "Arial",
  color: COLORS.red, align: "left", valign: "middle"
});
slide3.addText("22 Gwei (equilibrium)", {
  x: 2.8, y: 4.35, w: 1.7, h: 0.2,
  fontSize: 9, fontFace: "Arial",
  color: COLORS.accent, align: "right", valign: "middle"
});

// Min/Max/Avg table
slide3.addText("Min: 0.0 Gwei  |  Max: 1.3 Gwei  |  Avg: 0.1 Gwei", {
  x: 0.7, y: 4.6, w: 3.8, h: 0.25,
  fontSize: 10, fontFace: "Arial",
  color: COLORS.muted, align: "center", valign: "middle"
});

// Right: blob gas context
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 5.1, y: 1.1, w: 4.5, h: 2.0,
  fill: { color: COLORS.cardBg },
  line: { color: COLORS.purple, width: 1 }
});
slide3.addText("Blob Gas (EIP-4844)", {
  x: 5.3, y: 1.2, w: 4.1, h: 0.3,
  fontSize: 14, fontFace: "Arial", bold: true,
  color: COLORS.purple, align: "left", valign: "middle"
});
slide3.addText("Introduced for L2 data availability. Despite high blob gas volume, fee burns are negligible at current prices.", {
  x: 5.3, y: 1.55, w: 4.1, h: 0.5,
  fontSize: 11, fontFace: "Arial",
  color: COLORS.text, align: "left", valign: "middle"
});
slide3.addText("Avg Blob Gas: ~7.1M wei", {
  x: 5.3, y: 2.15, w: 4.1, h: 0.25,
  fontSize: 12, fontFace: "Arial", bold: true,
  color: COLORS.text, align: "left", valign: "middle"
});
slide3.addText("7-Day Blob Fee Burn: 0.15 ETH ($319)", {
  x: 5.3, y: 2.45, w: 4.1, h: 0.25,
  fontSize: 12, fontFace: "Arial", bold: true,
  color: COLORS.text, align: "left", valign: "middle"
});
slide3.addText("Blob fees are not yet a material burn driver.", {
  x: 5.3, y: 2.75, w: 4.1, h: 0.25,
  fontSize: 10, fontFace: "Arial", italic: true,
  color: COLORS.muted, align: "left", valign: "middle"
});

// Bottom insight box
slide3.addShape(pres.shapes.RECTANGLE, {
  x: 5.1, y: 3.4, w: 4.5, h: 1.6,
  fill: { color: COLORS.cardBg },
  line: { color: COLORS.orange, width: 1 }
});
slide3.addText("The Bottom Line", {
  x: 5.3, y: 3.5, w: 4.1, h: 0.3,
  fontSize: 14, fontFace: "Arial", bold: true,
  color: COLORS.orange, align: "left", valign: "middle"
});
slide3.addText("Current gas prices are ~220x below the 22 Gwei equilibrium assumption. This is a demand-side problem, not a protocol flaw. When on-chain activity recovers, the burn mechanism will reassert deflationary pressure. The protocol is working as designed — it simply needs more transactions.", {
  x: 5.3, y: 3.85, w: 4.1, h: 1.0,
  fontSize: 11, fontFace: "Arial",
  color: COLORS.text, align: "left", valign: "middle"
});

addFooter(slide3);

// ============================================
// SLIDE 4: Burn Leaderboard Categories
// ============================================
let slide4 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
addHeaderBar(slide4, "DeFi and ETH Transfers Account for 85% of Weekly Fee Burn");

// Left: horizontal bar chart for categories
slide4.addChart(pres.charts.BAR, [
  { name: "Burn (ETH)", labels: ["DeFi", "ETH Transfers", "Misc", "NFTs", "Contracts", "L2", "MEV", "Blobs"], values: [31, 22, 4, 3, 2, 0, 0, 0] }
], {
  x: 0.4, y: 1.0, w: 5.2, h: 3.6,
  barDir: "bar",
  chartColors: [COLORS.accent],
  chartArea: { fill: { color: COLORS.cardBg }, roundedCorners: true },
  catAxisLabelColor: COLORS.text,
  valAxisLabelColor: COLORS.muted,
  valGridLine: { color: "334155", size: 0.5 },
  catGridLine: { style: "none" },
  showValue: true,
  dataLabelPosition: "outEnd",
  dataLabelColor: COLORS.text,
  dataLabelFontSize: 10,
  showLegend: false,
  title: "7-Day Burn by Category (ETH)",
  titleColor: COLORS.text,
  titleFontSize: 12,
  titleBold: true
});

// Right: leaderboard table
slide4.addText("Top Burn Leaderboard", {
  x: 5.9, y: 1.1, w: 3.8, h: 0.3,
  fontSize: 14, fontFace: "Arial", bold: true,
  color: COLORS.accent, align: "left", valign: "middle"
});

slide4.addTable([
  [
    { text: "Contract / Category", options: { fill: { color: COLORS.accent }, color: COLORS.textDark, bold: true, fontSize: 10 } },
    { text: "Burn (ETH)", options: { fill: { color: COLORS.accent }, color: COLORS.textDark, bold: true, fontSize: 10, align: "right" } }
  ],
  [
    { text: "ETH Transfers", options: { fill: { color: COLORS.cardBg }, color: COLORS.text, fontSize: 10 } },
    { text: "21.74", options: { fill: { color: COLORS.cardBg }, color: COLORS.text, fontSize: 10, align: "right" } }
  ],
  [
    { text: "Tether USDT", options: { fill: { color: COLORS.secondary }, color: COLORS.text, fontSize: 10 } },
    { text: "13.55", options: { fill: { color: COLORS.secondary }, color: COLORS.text, fontSize: 10, align: "right" } }
  ],
  [
    { text: "DeFi (aggregate)", options: { fill: { color: COLORS.cardBg }, color: COLORS.text, fontSize: 10 } },
    { text: "31.00", options: { fill: { color: COLORS.cardBg }, color: COLORS.text, fontSize: 10, align: "right" } }
  ],
  [
    { text: "NFTs", options: { fill: { color: COLORS.secondary }, color: COLORS.text, fontSize: 10 } },
    { text: "3.00", options: { fill: { color: COLORS.secondary }, color: COLORS.text, fontSize: 10, align: "right" } }
  ],
  [
    { text: "Contract Creations", options: { fill: { color: COLORS.cardBg }, color: COLORS.text, fontSize: 10 } },
    { text: "2.00", options: { fill: { color: COLORS.cardBg }, color: COLORS.text, fontSize: 10, align: "right" } }
  ],
  [
    { text: "L2 / MEV / Blobs", options: { fill: { color: COLORS.secondary }, color: COLORS.text, fontSize: 10 } },
    { text: "0.00", options: { fill: { color: COLORS.secondary }, color: COLORS.text, fontSize: 10, align: "right" } }
  ]
], {
  x: 5.9, y: 1.5, w: 3.8, h: 2.1,
  border: { pt: 0.5, color: "334155" },
  colW: [2.8, 1.0],
  valign: "middle"
});

// Insight
slide4.addShape(pres.shapes.RECTANGLE, {
  x: 5.9, y: 3.8, w: 3.8, h: 1.0,
  fill: { color: COLORS.cardBg },
  line: { color: COLORS.muted, width: 0.5 }
});
slide4.addText("DeFi + ETH transfers = ~85% of all burns. But at 0.1 Gwei, even the leaderboard leaders burn negligible amounts. A single high-activity day during DeFi summer would dwarf the entire week's burn.", {
  x: 6.0, y: 3.85, w: 3.6, h: 0.9,
  fontSize: 10, fontFace: "Arial",
  color: COLORS.text, align: "left", valign: "middle"
});

addFooter(slide4);

// ============================================
// SLIDE 5: Staking and Validator Economics
// ============================================
let slide5 = pres.addSlide({ masterName: "CONTENT_SLIDE" });
addHeaderBar(slide5, "38.9M ETH Staked at 2.7% Issuance Rewards with Minimal Tips and MEV");

// Left: big stat cards
