// Reward breakdown donut chart
slide5.addChart(pres.charts.DOUGHNUT, [
  { name: "Rewards", labels: ["Issuance (2.7%)", "Tips (0.1%)", "MEV (0.1%)"], values: [2.7, 0.1, 0.1] }
