  legendPos: "b",
  legendColor: COLORS.text,
  legendFontSize: 9,
  title: "Validator Reward Composition",
  titleColor: COLORS.text,
  titleFontSize: 11,
  titleBold: true,
  holeSize: 55
});

// Right: reward table
slide5.addText("Validator Rewards Breakdown", {
  x: 4.0, y: 1.1, w: 5.5, h: 0.3,
  fontSize: 14, fontFace: "Arial", bold: true,
  color: COLORS.accent, align: "left", valign: "middle"
});

slide5.addTable([
  [
    { text: "Reward Type", options: { fill: { color: COLORS.accent }, color: COLORS.textDark, bold: true, fontSize: 11 } },
    { text: "Amount", options: { fill: { color: COLORS.accent }, color: COLORS.textDark, bold: true, fontSize: 11, align: "center" } },
    { text: "APR", options: { fill: { color: COLORS.accent }, color: COLORS.textDark, bold: true, fontSize: 11, align: "center" } }
  ],
  [
    { text: "Issuance", options: { fill: { color: COLORS.cardBg }, color: COLORS.text, fontSize: 11 } },
    { text: "0.9 ETH/validator", options: { fill: { color: COLORS.cardBg }, color: COLORS.text, fontSize: 11, align: "center" } },
    { text: "2.7%", options: { fill: { color: COLORS.cardBg }, color: COLORS.accent, fontSize: 11, align: "center", bold: true } }
  ],
